from os import path

from taf.gnb.oam.coam.cu.utilities.http_client import HttpClient
from taf.gnb.oam.coam.cu.utilities.multipart_encoder import MultipartEncoder


class ASMLicensedHttpClient(HttpClient):
    def __init__(self, base_url, connection_alias):
        super(ASMLicensedHttpClient, self).__init__(connection_alias)
        self.base_url = base_url + "/api/licensed/v1"

    def perform_commissioning(self, scf_file, should_activate, timeout):
        endpoint = f'/staged-plans/operations/{"provisions" if should_activate else "pre-activations"}'
        plan_name = path.splitext(path.split(scf_file)[1])[0]

        with open(scf_file, "rb") as file:
            multipart_data = MultipartEncoder(
                fields={"planFile": (plan_name, file, "text/xml"),
            })

            headers = {
                "Content-Type": multipart_data.content_type,
            }

            return self._send_post_request(endpoint=endpoint, data=str(multipart_data), timeout=timeout,
                                           headers=headers, log_payload=False)

    def get_status_of_perform_commissioning(self, operation_id, timeout):
        endpoint = f'/staged-plans/operations/provisions/{operation_id}'
        headers = {
            "Content-Type": "application/json",
        }

        return self._send_get_request(endpoint=endpoint, headers=headers, timeout=timeout)

    def get_status_of_perform_commissioning_without_activation(self, operation_id, timeout=30):
        endpoint = f'/staged-plans/operations/pre-activations/{operation_id}'
        headers = {
            "Content-Type": "application/json",
        }

        return self._send_get_request(endpoint=endpoint, headers=headers, timeout=timeout)

    def trigger_screl_collection(self, coverage, screl_type, timeout=30):
        endpoint = '/screls'
        headers = {
            "accept": "application/json",
            "Content-Type": "application/json",
        }
        data = {
            'reason': 'Collect screl',
            'coverage': coverage,
            'originator': 'M2M',
            'heartbeat': True,
            'screlType': screl_type
        }

        return self._send_post_request(endpoint=endpoint, json=data, timeout=timeout, headers=headers)

