    def trigger_snapshot(self, filter_regx, coverage, originator, snapshot_type, timeout=30):
        endpoint = '/snapshot/operations'
        headers = {
            "accept": "application/json",
            "Content-Type": "application/json",
        }
        data = {
            "coverage": coverage,
            "originator": originator,
            "heartbeat": True,
            "snapshotType": snapshot_type,
        }
        if filter_regx is not None:
            data["filterRegx"] = filter_regx
        return self._send_post_request(endpoint=endpoint, headers=headers, json=data, timeout=timeout)

